import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
const kbPath = 'server/kristy_perimeter_kb.json';
const pinPath = 'server/test/acceptance/twoLinePin.js';
let kbText = readFileSync(kbPath, 'utf8');
let pinText = readFileSync(pinPath, 'utf8');
const kb = JSON.parse(kbText);
const source = { name: 'EWG: BPA in Canned Food', url: 'https://www.ewg.org/research/bpa-canned-food' };
const additions = {
  canned_soup: {
    buying_tips: [
      'Many food cans are lined with an epoxy made with BPA. Fresh or frozen soup has no can lining.',
      'In a can, pick one that says BPA-free on the label over one that says nothing.',
    ],
    watch_out: \"BPA-free is the maker's word. EWG's survey found makers define it as they wish. Makers that dropped BPA did not disclose the lining that replaced it.\",
  },
  canned_fish_choosing: {
    buying_tips: [
      'An epoxy made with BPA lines many food cans. Fresh or frozen fish comes without a can lining.',
      'Choose a can that says BPA-free on its label over a can that says nothing.',
    ],
    watch_out: \"BPA-free is a claim from the maker. EWG found that makers define it as they wish. In EWG's survey, makers that dropped BPA did not disclose their replacement lining.\",
  },
  canned_tuna: {
    buying_tips: [
      'Many food cans use a lining of epoxy made with BPA. Fresh or frozen tuna has no can lining.',
      'For canned tuna, choose one that says BPA-free on the label over one that says nothing.',
    ],
    watch_out: \"The maker supplies the BPA-free claim. EWG's survey found companies define it as they wish. Those that dropped BPA did not disclose what lining replaced it.\",
  },
  canned_coconut_milk: {
    buying_tips: [
      'Many food cans have an epoxy lining made with BPA. Where the same coconut milk is sold in glass, the jar has no can lining.',
      'On canned coconut milk, choose a label that says BPA-free over a can that says nothing.',
    ],
    watch_out: \"A BPA-free label gives the maker's word. EWG reported that makers define it as they wish. Its survey found makers that dropped BPA did not disclose which lining they used instead.\",
  },
};
const indented = (obj, spaces) => JSON.stringify(obj, null, 2).split('\\n').map(line => ' '.repeat(spaces) + line).join('\\n');
const replaceOnce = (text, before, after) => {
  assert.equal(text.split(before).length, 2, 'replacement must have exactly one match');
  return text.replace(before, () => after);
};
for (const [id, copy] of Object.entries(additions)) {
  const entry = kb.entries.find(e => e.id === id);
  assert.ok(entry);
  const oldEntry = indented(entry, 4);
  assert.equal(entry.sources.some(s => s.url === source.url), false);
  entry.buying_tips.push(...copy.buying_tips);
  entry.watch_out.push(copy.watch_out);
  entry.sources.push(source);
  kbText = replaceOnce(kbText, oldEntry, indented(entry, 4));
  const pinPattern = new RegExp('"'^  "'"' + id + '\": (\\\\{[\\\\s\\\\S]*?"'^  '"\\\\})(?=,?\\\\n)', 'm');
  const match = pinText.match(pinPattern);
  assert.ok(match, id + ' existing pin');
  const pin = JSON.parse(match[1]);
  for (const field of ['buying_tips', 'watch_out', 'sources']) pin[field] = entry[field];
  const updated = '  \"' + id + '\": ' + indented(pin, 2).trimStart();
  pinText = replaceOnce(pinText, match[0], updated);
}
const pick = kb.entries.find(e => e.id === 'pick_canned_tomatoes');
const oldPick = indented(pick, 4);
pick.decision = 'Skip dented, rusted or swollen cans; read the can for BPA-free; the date is a quality mark.';
pick.sources.push(source);
kbText = replaceOnce(kbText, oldPick, indented(pick, 4));
const pickPin = { decision: pick.decision, sources: pick.sources };
pinText = replaceOnce(pinText, 'const PICK_PINS = {\\n', 'const PICK_PINS = {\\n  \"pick_canned_tomatoes\": ' + indented(pickPin, 2).trimStart() + ',\\n');
pinText = replaceOnce(pinText, \"const picks = ['pick_sausage', 'pick_jerky', 'pick_juice'];\", \"const picks = ['pick_sausage', 'pick_jerky', 'pick_juice', 'pick_canned_tomatoes'];\");
pinText = replaceOnce(pinText, \"'all two-line pins', 184\", \"'all two-line pins', 185\");
pinText = replaceOnce(pinText, 'const CONCERN = new Set([', \"const CONCERN = new Set(['canned_soup', 'canned_fish_choosing', 'canned_tuna', 'pick_canned_tomatoes', 'canned_coconut_milk', \");
assert.deepEqual(JSON.parse(kbText), kb);
writeFileSync(kbPath, kbText);
writeFileSync(pinPath, pinText);
console.log('Updated five KB entries and their literal pins; preserved all other entry bytes.');
JS"

